effect.shader:
// Classic Halftone Dots: dot size driven by source luminance
// Dark areas -> larger dots, Light areas -> smaller dots

const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);
float greyScale(vec3 c){ return dot(c, LUMA); }
mat2 rot(float a){ float s=sin(a), c=cos(a); return mat2(c,-s,s,c); }

// Optional 3x3 luminance smooth to avoid flicker at high frequency
float smoothLum(vec2 uv){
  if(smoothSource <= 0.0) return greyScale(texture2DCv(inputImg.texture, uv).rgb);
  vec2 texel = 1.0 / getTexSize(inputImg.size);
  float r = clamp(smoothSource, 0.0, 2.0);
  vec2 o = texel * r;
  float acc = 0.0; float w = 0.0;
  for(int j=-1;j<=1;j++){
    for(int i=-1;i<=1;i++){
      float ww = (i==0 && j==0) ? 2.0 : 1.0;
      acc += greyScale(texture2DCv(inputImg.texture, uv + vec2(i,j)*o).rgb) * ww;
      w += ww;
    }
  }
  return acc / max(w, 1.0);
}

void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float lum = smoothLum(uv);            // 0=black, 1=white

  // Build rotated grid coordinates in pixel space, normalize by height for AR stability
  float ang = radians(dotsAngle);
  vec2 shiftPx = vec2(shiftX, -shiftY);
  vec2 uvShift = uv + shiftPx / acScreenSize;
  vec2 p = (uvShift - 0.5) * acScreenSize; // pixel space centered
  vec2 s = rot(ang) * p;                    // rotate grid
  vec2 st = s / max(acScreenSize.y, 1.0);   // normalize

  // Frequency: how many dots per height
  float freq = max(dotsFrequency, 0.0001);
  vec2 grid = st * freq;
  vec2 f = fract(grid) - 0.5;               // cell-local coords in [-0.5, 0.5]

  // Allow elliptical dots via relative width
  f.x *= dotsRelWidth;
  float dist = length(f);

  // Dot radius from luminance: darker -> larger
  // dotsLighten shifts the curve (+ makes dots lighter/smaller)
  float rLuma = clamp(1.0 - lum + dotsLighten, 0.0, 1.0);
  float radius = 0.5 * rLuma;               // 0..0.5 cell radius

  // Edge softness: higher sharpness -> crisper edges
  float edge = 0.01 / max(dotsSharpness, 0.0001);
  float dotMask = 1.0 - smoothstep(radius - edge, radius + edge, dist);

  // Mode swap: 0 = black dots on white, 1 = white dots on black
  if(dotsMode == 1) dotMask = 1.0 - dotMask;

  vec3 c0 = color0.rgb; // dot color (black by default)
  vec3 c1 = color1.rgb; // background color (white by default)
  vec3 halftone = mix(c1, c0, dotMask);

  float a = src.a * alpha;
  gl_FragColor = vec4(halftone, 1.0) * a;
}
